python -c "
from parse import Parser, FormatSpecError

# Edge cases for brace matching
edge_cases = [
    # Should raise errors
    ('{{{', True),       # escaped {{ + orphan {
    ('}}}', True),       # escaped }} + orphan }
    ('{{abc}', True),    # escaped {{ followed by field abc without closing brace... wait no
    ('{a}{b}', False),   # two separate fields - valid
    ('{a} and {b}', False),  # two fields with text - valid  
    ('hello world', False),  # no braces - valid
    ('{{}}', False),     # just escaped braces - valid
    ('{{a}}', False),    # escaped {a} - valid
    ('{}', False),       # empty field name - valid
]

print('Edge case tests:')
for pattern, should_error in edge_cases:
    try:
        p = Parser(pattern)
        if should_error:
            print(f'  FAIL: {repr(pattern):20} -> No error but should have')
        else:
            print(f'  PASS: {repr(pattern):20} -> OK (expr: {repr(p._expression)})')
    except FormatSpecError as e:
        if should_error:
            print(f'  PASS: {repr(pattern):20} -> FormatSpecError')
        else:
            print(f'  FAIL: {repr(pattern):20} -> Unexpected error: {e}')
" 2>&1 | grep -v SyntaxWarning
